<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Penerimaan', href: '/owner/payments' }, { title: 'Catat transfer', href: '#' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import { untrack } from 'svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';
    type InvoiceTarget = { id: number; invoice_number: string; resident: string | null; room: string | null; balance_rupiah: number; due_date: string };
    type DepositTarget = { id: number; resident: string | null; required_amount_rupiah: number; balance_rupiah: number };
    let { invoices, deposits, selected_invoice_id, selected_deposit_id, initial, idempotency_key }: { invoices: InvoiceTarget[]; deposits: DepositTarget[]; selected_invoice_id: number | null; selected_deposit_id: number | null; initial: { occurred_on: string; method: string }; idempotency_key: string } = $props();
    let selectedInvoice = $state(untrack(() => selected_invoice_id?.toString() ?? ''));
    let selectedDeposit = $state(untrack(() => selected_deposit_id?.toString() ?? ''));
    const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value);
</script>

<AppHead title="Catat penerimaan" />
<main class="mx-auto w-full max-w-3xl space-y-6 p-4 md:p-8">
    <header class="space-y-2"><p class="text-sm font-medium text-muted-foreground">Keuangan</p><h1 class="text-3xl font-semibold tracking-tight">Catat transfer yang diterima</h1><p class="text-sm text-muted-foreground">Jumlah alokasi harus sama dengan transfer aktual. Pembayaran sewa dan deposit dapat dicatat sebagai satu transfer gabungan.</p></header>
    <Form action="/owner/payments" method="post" class="space-y-6 rounded-xl border bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}
        <input type="hidden" name="idempotency_key" value={idempotency_key} />
        <section class="grid gap-4 sm:grid-cols-2"><div class="space-y-2"><label for="amount_rupiah" class="text-sm font-medium">Total transfer aktual (Rupiah)</label><Input id="amount_rupiah" name="amount_rupiah" type="number" min={1} step={1} required /><InputError message={errors.amount_rupiah} /></div><div class="space-y-2"><label for="occurred_on" class="text-sm font-medium">Tanggal diterima</label><Input id="occurred_on" name="occurred_on" type="date" value={initial.occurred_on} required /><InputError message={errors.occurred_on} /></div><div class="space-y-2"><label for="method" class="text-sm font-medium">Metode</label><select id="method" name="method" value={initial.method} required class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="bank_transfer">Transfer bank</option><option value="cash">Tunai</option><option value="e_wallet">Dompet digital</option><option value="other">Lainnya</option></select><InputError message={errors.method} /></div><div class="space-y-2"><label for="external_reference" class="text-sm font-medium">Referensi transfer</label><Input id="external_reference" name="external_reference" maxlength={160} /><InputError message={errors.external_reference} /></div></section>
        <section class="space-y-4 rounded-lg border p-4"><div><h2 class="font-semibold">Alokasi ke tagihan sewa</h2><p class="text-sm text-muted-foreground">Pilih tagihan jika sebagian transfer untuk sewa.</p></div>{#if invoices.length === 0}<p class="text-sm text-muted-foreground">Tidak ada saldo tagihan sewa.</p>{:else}<div class="grid gap-3 sm:grid-cols-[1fr_12rem]"><div class="space-y-2"><label for="invoice_allocation" class="text-sm font-medium">Tagihan</label><select id="invoice_allocation" bind:value={selectedInvoice} class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Tidak dialokasikan ke tagihan</option>{#each invoices as invoice (invoice.id)}<option value={invoice.id}>{invoice.invoice_number} · {invoice.resident ?? 'Penyewa'} · sisa {money(invoice.balance_rupiah)}</option>{/each}</select>{#if selectedInvoice}<input type="hidden" name="allocations[0][invoice_id]" value={selectedInvoice} /><label for="invoice_amount" class="mt-3 block text-sm font-medium">Alokasi sewa (Rupiah)</label><Input id="invoice_amount" name="allocations[0][amount_rupiah]" type="number" min={1} step={1} required /><InputError message={errors['allocations.0.amount_rupiah']} />{/if}<InputError message={errors['allocations.0.invoice_id']} /></div></div>{/if}</section>
        <section class="space-y-4 rounded-lg border p-4"><div><h2 class="font-semibold">Alokasi ke deposit jaminan</h2><p class="text-sm text-muted-foreground">DP booking dan deposit jaminan memakai kewajiban yang sama.</p></div>{#if deposits.length === 0}<p class="text-sm text-muted-foreground">Tidak ada saldo kewajiban deposit.</p>{:else}<div class="grid gap-3 sm:grid-cols-[1fr_12rem]"><div class="space-y-2"><label for="deposit_allocation" class="text-sm font-medium">Akun deposit</label><select id="deposit_allocation" bind:value={selectedDeposit} class="h-10 w-full rounded-md border bg-background px-3 text-sm"><option value="">Tidak dialokasikan ke deposit</option>{#each deposits as deposit (deposit.id)}<option value={deposit.id}>{deposit.resident ?? 'Penyewa'} · kewajiban {money(deposit.required_amount_rupiah)} · diterima {money(deposit.balance_rupiah)}</option>{/each}</select>{#if selectedDeposit}<input type="hidden" name="allocations[1][deposit_account_id]" value={selectedDeposit} /><label for="deposit_amount" class="mt-3 block text-sm font-medium">Alokasi deposit (Rupiah)</label><Input id="deposit_amount" name="allocations[1][amount_rupiah]" type="number" min={1} step={1} required /><InputError message={errors['allocations.1.amount_rupiah']} />{/if}<InputError message={errors['allocations.1.deposit_account_id']} /></div></div>{/if}</section>
        <InputError message={errors.allocations} /><InputError message={errors.idempotency_key} /><div class="flex flex-wrap justify-end gap-2"><Link href="/owner/payments" class="inline-flex items-center rounded-md border px-4 py-2 text-sm">Batal</Link><Button type="submit" disabled={processing}>{processing ? 'Mencatat…' : 'Catat penerimaan'}</Button></div>
    {/snippet}</Form>
</main>
